import { TooltipPlacement, TooltipBoundaries, TooltipPosition } from '../Tooltip/Tooltip.types';

/* eslint-disable max-params */
const generatePlacementMapper = (childEl: HTMLElement, ttEl: HTMLElement, space: number) => {
  const elRect = childEl.getBoundingClientRect();

  const positionByPlacement = {
    left: {
      x: elRect.left - (ttEl.offsetWidth + space),
      y:
        elRect.top +
        window.scrollY +
        ((childEl.offsetHeight || childEl.clientHeight) - ttEl.offsetHeight) / 2,
      arrowX: '100%',
      arrowY: 'calc(50% - 5px)',
      arrowBorder: 'transparent transparent transparent black',
    },
    right: {
      x: elRect.right + space,
      y:
        elRect.top +
        window.scrollY +
        ((childEl.offsetHeight || childEl.clientHeight) - ttEl.offsetHeight) / 2,
      arrowX: '-10px',
      arrowY: 'calc(50% - 5px)',
      arrowBorder: 'transparent black transparent transparent',
    },
    top: {
      x: elRect.left + ((childEl.offsetWidth || childEl.clientWidth) - ttEl.offsetWidth) / 2,
      y: window.scrollY + elRect.top - (ttEl.offsetHeight + space),
      arrowY: '100%',
      arrowX: 'calc(50% - 5px)',
      arrowBorder: 'black transparent transparent transparent',
    },
    bottom: {
      x: elRect.left + ((childEl.offsetWidth || childEl.clientWidth) - ttEl.offsetWidth) / 2,
      y: window.scrollY + elRect.bottom + space,
      arrowY: '-10px',
      arrowX: 'calc(50% - 5px)',
      arrowBorder: 'transparent transparent black transparent',
    },
  };

  return (placement: TooltipPlacement) => positionByPlacement[placement];
};

const getInvertedPlacement = (placement: TooltipPlacement): TooltipPlacement => {
  const invertedPlacements: { [key: string]: TooltipPlacement } = {
    left: 'right',
    right: 'left',
    top: 'bottom',
    bottom: 'top',
  };
  return invertedPlacements[placement];
};

// istanbul ignore next
const restrictRect = (position: TooltipPosition, rect: TooltipBoundaries) => {
  const restrictedPosition = { ...position };

  if (restrictedPosition.x < rect.left) restrictedPosition.x = rect.left;
  else if (restrictedPosition.x > rect.right) restrictedPosition.x = rect.right;
  if (restrictedPosition.y < rect.top) restrictedPosition.y = rect.top;
  else if (restrictedPosition.y > rect.bottom) restrictedPosition.y = rect.bottom;

  return restrictedPosition;
};

const getPosition = (
  childEl: HTMLElement,
  ttEl: HTMLElement,
  { space, placement, isMobile }: { space: number; placement: TooltipPlacement; isMobile: boolean }
): TooltipPosition => {
  let recursiveCounter = 1;
  let actualPlacement = placement;

  if (isMobile && (placement === 'left' || placement === 'right')) {
    actualPlacement = 'bottom';
  }

  const boundaries = {
    left: space,
    top: space,
    right: document.body.clientWidth - (ttEl.clientWidth + space),
    bottom: window.innerHeight + window.scrollY - (ttEl.clientHeight + space),
  };

  const getPlacement = generatePlacementMapper(childEl, ttEl, space);
  let position = getPlacement(actualPlacement);

  const isHorizontal = actualPlacement === 'left' || actualPlacement === 'right';
  const isVertical = actualPlacement === 'top' || actualPlacement === 'bottom';

  const hitLeft = position.x < boundaries.left;
  const hitRight = position.x > boundaries.right;
  const hitTop = position.y < boundaries.top;
  const hitBottom = position.y > boundaries.bottom;

  // istanbul ignore next
  if (recursiveCounter < 3) {
    if ((isHorizontal && hitLeft) || hitRight || (isVertical && hitTop) || hitBottom) {
      recursiveCounter += 1;
      actualPlacement = getInvertedPlacement(actualPlacement);
      position = getPlacement(actualPlacement);
    }
  }

  const restrictedPosition = restrictRect(position, boundaries);
  return restrictedPosition;
};

export default getPosition;
